#include <iostream>
#include <cstdio>

int main() {
    // Demonstrate character integer values and ASCII representation
    char ch = 'a';
    int asciiVal = static_cast<int>(ch);
    std::cout << "Character '" << ch << "' has ASCII value " << asciiVal << ".\n";

    // Demonstrate assignment chain (right-to-left associativity)
    int x, y, z;
    x = y = z = 100;
    std::cout << "x = " << x << ", y = " << y << ", z = " << z << "\n";

    // Demonstrate assignment inside condition reading from stdin
    int inputChar;
    int count = 0;
    while ((inputChar = std::cin.get()) != EOF) {
        if (inputChar != '\n') {
            ++count;
        }
    }
    std::cout << "Processed " << count << " non-newline characters." << std::endl;
    return 0;
}

#include <iostream>
#include <cstdio>

int main() {
    unsigned int aCount = 0;
    unsigned int bCount = 0;
    unsigned int cCount = 0;
    unsigned int otherCount = 0;
    int grade;

    while ((grade = std::cin.get()) != EOF) {
        switch (grade) {
            case 'A':
            case 'a':
                ++aCount;
                break;

            case 'B':
            case 'b':
                ++bCount;
                break;

            case 'C':
            case 'c':
                ++cCount;
                break;

            // Ignore whitespace characters from buffer
            case '\n':
            case '\t':
            case ' ':
                break;

            default:
                ++otherCount;
                break;
        }
    }

    std::cout << "Totals:\n";
    std::cout << "A: " << aCount << "\n";
    std::cout << "B: " << bCount << "\n";
    std::cout << "C: " << cCount << "\n";
    std::cout << "Other: " << otherCount << "\n";
    return 0;
}
